(function(){
const ok=new Set(['everyday','date','team']);
const configs={everyday:{k:'EVERYDAY, TOGETHER',lead:'友達、家族、旅先で。いま一緒にいる2〜8人が、同じ質問にひとりずつ答えます。',q:'最近、つい笑ってしまった出来事は？',s:[['/assets/lp-day-cafe.webp','友達とカフェ','最近、つい笑ってしまった出来事は？','友達'],['/assets/lp-family-talk.webp','家族の食卓','今の暮らしで、意外と気に入っている小さな習慣は？','家族'],['/assets/lp-team-break.webp','休憩時間','最近ハマっていること、または気になっていることは？','休憩'],['/assets/lp-day-trip.webp','旅の途中','次に会うときまでに、お互い試しておいたら面白そうなことは？','旅'],['/assets/lp-weekend-two.webp','休日のふたり','今日の会話の続きをするなら、次はどんなことを一緒に話してみたい？','ふたり']]},date:{k:'DATE, TOGETHER',lead:'初めて会う夜も、少し深く話したい夜も。気負わず、同じ質問を順番に。',q:'最近、予定外だったけれど嬉しかったことは？',s:[['/assets/lp-city-date.webp','街の夜、初対面','最近、予定外だったけれど嬉しかったことは？','初対面'],['/assets/lp-intimate-livingroom.webp','ゆっくり話す夜','最近、自分に「よくやった」と言いたいことは？','おうち'],['/assets/lp-home-party.webp','家で過ごす時間','これから、なんて呼んで欲しい？','集まり'],['/assets/lp-weekend-two.webp','休日のふたり','いつか一緒に見てみたい景色や行ってみたい場所は？','休日'],['/assets/lp-late-cafe.webp','夜のもう一問','意外な場面で、誰かや何かにときめいたことは？','カフェ']]},team:{k:'TEAM, TOGETHER',lead:'同僚やイベントの初対面でも、スマホ1台。答えたくないときはパスできます。',q:'最近、仕事や学びで「面白い」と感じたことは？',s:[['/assets/lp-team-break.webp','チームの休憩','最近、仕事や学びで「面白い」と感じたことは？','同僚'],['/assets/lp-bar-first-meet.webp','初対面の集まり','これから、なんて呼んで欲しい？','交流会'],['/assets/lp-day-cafe.webp','イベントのあと','詳しくなりたいけれど、まだ時間を取れていないテーマは？','イベント'],['/assets/lp-day-trip.webp','チームの旅','最近、仕事とは別に時間を使っている興味は？','旅先'],['/assets/lp-team-break.webp','次のプロジェクト','最近、やり方を変えてよかった仕事の習慣は？','仕事']]}};
configs.everyday.s.push(['/assets/lp-izakaya-friends.webp','居酒屋の友人たち','最近、つい笑ってしまった出来事は？','居酒屋'],['/assets/lp-city-date.webp','夜のふたり','最近、予定外だったけれど嬉しかったことは？','夜のふたり']);
const valid=v=>ok.has(v)?v:null;
function route(){let storage=null;try{storage=window.localStorage}catch(_){}return window.MingleExperienceRouting?.resolve({search:location.search,storage,now:Date.now()})||{experience:'everyday',source:'default'}}
function setup(){const h=document.querySelector('.hero'),people=document.querySelector('.people');if(!document.querySelector('.experience-picker')){const p=document.createElement('section');p.className='experience-picker';p.innerHTML='<div><p class="eyebrow">CHOOSE YOUR MOMENT</p><h2>どんな時間に使う？</h2><p>選んだ場面に合わせて、写真と質問の例が変わります。</p></div><div class="experience-buttons"><button data-experience-choice="everyday" aria-pressed="false">いつもの時間</button><button data-experience-choice="date" aria-pressed="false">ふたりの夜</button><button data-experience-choice="team" aria-pressed="false">チームの時間</button><button data-experience-reset>選び直す</button></div>';h.after(p)}if(!document.querySelector('.usecases')){const u=document.createElement('section');u.className='usecases';u.innerHTML='<div class="usecases-intro"><p class="eyebrow">MOMENTS TO MINGLE</p><h2>写真で見る、<br>使う場面。</h2></div><div data-usecases class="usecase-list"></div>';people.after(u)}const hm=document.querySelector('.hero-message');hm.querySelector('.eyebrow').dataset.heroKicker='';hm.querySelector('h1').dataset.heroTitle='';hm.querySelector('p:not(.eyebrow)').dataset.heroLead='';}
function apply(n){const c=configs[n]||configs.everyday;document.documentElement.dataset.experience=n;document.body.dataset.experience=n;document.querySelector('[data-hero-kicker]').textContent=c.k;document.querySelector('[data-hero-title]').innerHTML='<span>スマホ1台で遊ぶ、</span><br><em>会話カードゲーム。</em>';document.querySelector('[data-hero-lead]').textContent=c.lead;window.MingleDemo?.setQuestions(c.s.slice(0,3).map(d=>d[2]));window.MingleCarousel?.setScenes(c.s);window.MingleCarousel?.reset();document.querySelectorAll('[data-slide]').forEach((s,i)=>{const d=c.s[i],im=s.querySelector('img');im.src=d[0];im.alt=d[1]+'でMingle.Cardsを楽しむ';s.querySelector('small').textContent=d[1]});document.querySelectorAll('[data-dot]').forEach((b,i)=>{b.textContent=c.s[i][3];b.setAttribute('aria-label',c.s[i][1])});const lower=c.s.slice(0,n==='team'?4:5);document.querySelector('[data-usecases]').innerHTML=lower.map((d,i)=>`<article class="usecase"><img src="${d[0]}" alt="${d[1]}で会話する様子" loading="lazy"><div><p class="eyebrow">質問の例</p><h3>${d[1]}</h3><p>${d[2]}</p><a href="https://mingle.cards/">Mingleで遊ぶ ↗</a></div></article>`).join('');document.querySelectorAll('[data-experience-choice]').forEach(b=>{const a=b.dataset.experienceChoice===n;b.classList.toggle('is-selected',a);b.setAttribute('aria-pressed',String(a))});}
function choose(v){if(!valid(v))return;try{window.MingleExperienceRouting?.remember(window.localStorage,v,Date.now())}catch(_){}apply(v);const u=window.MingleExperienceRouting?.selectionUrl(location.href,v);if(u)history.replaceState({},'',u)}
window.MingleExperience={configs,apply,resolve:()=>route().experience};document.addEventListener('DOMContentLoaded',()=>{setup();apply(route().experience);document.querySelectorAll('[data-experience-choice]').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.experienceChoice)));document.querySelector('[data-experience-reset]')?.addEventListener('click',()=>{try{window.MingleExperienceRouting?.forget(window.localStorage)}catch(_){}const u=window.MingleExperienceRouting?.resetUrl(location.href);if(u)history.replaceState({},'',u);apply('everyday')})});
})();
